---------------------

-- Set programs that you use
local terminal    = "ghostty"
local fileManager = "thunar"
local menu = "noctalia msg panel-toggle launcher"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/configuring/core/autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function () 
  hl.exec_cmd(noctalia)
  -- Publish this instance's display to systemd and D-Bus. Without it,
  -- D-Bus-activated apps (portals, single-instance apps, KDE services) keep
  -- using the Wayland socket of a previous compositor. Source of truth:
  -- ports/hyprland/dev/session-env.sh (mise run hypr:install-session-env).
  hl.exec_cmd("$HOME/.config/hypr/session-env.sh")
  -- hl.exec_cmd(terminal)
  -- hl.exec_cmd("nm-applet")
  -- hl.exec_cmd("waybar & hyprpaper & firefox")
end)

-- Do not leave a dead socket in the user manager after this session exits.
hl.on("hyprland.shutdown", function ()
  hl.exec_cmd("$HOME/.config/hypr/session-env.sh --clear")
end)


